using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
using TMPro;
using System.Collections.Generic;
using System.Linq;

public static class DressOffroadCourse
{
    const string Dir = "Assets/Environments/OffroadCourse/Scenery";
    class Route { public Vector3[] p; public float width; }
    static Route[] routes; static Transform root, group; static Mesh rockMesh, coneMesh;
    static Material timber, stone, lightStone, leaf, olive, pine, bark, panel, gold, white, roof;
    static TMP_FontAsset font; static System.Random rng; static int rockCount, bushCount, treeCount, signCount;
    static float R(float a, float b) => Mathf.Lerp(a,b,(float)rng.NextDouble());
    static Material Mat(string name, Color color) { var m=new Material(Shader.Find("Universal Render Pipeline/Lit")){name=name};m.color=color;m.SetFloat("_Smoothness",.08f);AssetDatabase.CreateAsset(m,Dir+"/"+name+".mat");return m; }
    static Route LoadRoute(string name,float width) { var v=root.Find(name).GetComponent<MeshFilter>().sharedMesh.vertices;var p=new Vector3[v.Length/2];for(int i=0;i<p.Length;i++)p[i]=(v[i*2]+v[i*2+1])*.5f;return new Route{p=p,width=width}; }
    static float Distance(Vector3 q, Route route) { float best=float.MaxValue;for(int i=1;i<route.p.Length;i++){var a=route.p[i-1];var b=route.p[i];var d=new Vector2(b.x-a.x,b.z-a.z);var delta=new Vector2(q.x-a.x,q.z-a.z);float t=Mathf.Clamp01(Vector2.Dot(delta,d)/Mathf.Max(.0001f,d.sqrMagnitude));best=Mathf.Min(best,(delta-d*t).magnitude);}return best; }
    static bool Clear(Vector3 p,float radius) => routes.All(r=>Distance(p,r)>r.width*.5f+radius+1.2f);
    static bool InBackgroundHill(Vector3 p,float radius) { foreach(var r in Object.FindObjectsByType<MeshRenderer>()){if(r.name!="Distant grassy hill")continue;var b=r.bounds;if(p.x>b.min.x-radius&&p.x<b.max.x+radius&&p.z>b.min.z-radius&&p.z<b.max.z+radius)return true;}return false; }
    static float Ground(Vector3 p) { float best=float.NegativeInfinity;foreach(var h in Physics.RaycastAll(new Vector3(p.x,40,p.z),Vector3.down,80)){if(h.collider.GetComponent<TestDriveSurface>()!=null||h.collider.name=="Ground"||h.collider.name=="Offroad ground")best=Mathf.Max(best,h.point.y);}return float.IsNegativeInfinity(best)?-.05f:best; }
    static Vector3 OnGround(Vector3 p){p.y=Ground(p);return p;}
    static Vector3 At(Route r,float distance,out Vector3 forward) { float d=0;for(int i=1;i<r.p.Length;i++){float length=Vector3.Distance(new Vector3(r.p[i-1].x,0,r.p[i-1].z),new Vector3(r.p[i].x,0,r.p[i].z));if(d+length>=distance){forward=r.p[i]-r.p[i-1];forward.y=0;forward.Normalize();return Vector3.Lerp(r.p[i-1],r.p[i],(distance-d)/length);}d+=length;}forward=(r.p[r.p.Length-1]-r.p[r.p.Length-2]).normalized;return r.p[r.p.Length-1]; }
    static GameObject Shape(string name,Mesh mesh,Vector3 p,Vector3 scale,Material mat,Transform parent=null) {var g=new GameObject(name,typeof(MeshFilter),typeof(MeshRenderer));g.transform.SetParent(parent?parent:group,false);g.transform.position=p;g.transform.localScale=scale;g.GetComponent<MeshFilter>().sharedMesh=mesh;g.GetComponent<Renderer>().sharedMaterial=mat;return g;}
    static GameObject Box(string name,Vector3 p,Vector3 size,Material mat,Transform parent=null) { var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;Object.DestroyImmediate(g.GetComponent<Collider>());g.transform.SetParent(parent?parent:group);g.transform.position=p;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=mat;return g; }
    static Transform Folder(string name) {var g=new GameObject(name);g.transform.SetParent(group,false);return g.transform;}
    static Mesh RockMesh() {float t=(1+Mathf.Sqrt(5))/2;var v=new[]{new Vector3(-1,t,0),new Vector3(1,t,0),new Vector3(-1,-t,0),new Vector3(1,-t,0),new Vector3(0,-1,t),new Vector3(0,1,t),new Vector3(0,-1,-t),new Vector3(0,1,-t),new Vector3(t,0,-1),new Vector3(t,0,1),new Vector3(-t,0,-1),new Vector3(-t,0,1)};int[] faces={0,11,5,0,5,1,0,1,7,0,7,10,0,10,11,1,5,9,5,11,4,11,10,2,10,7,6,7,1,8,3,9,4,3,4,2,3,2,6,3,6,8,3,8,9,4,9,5,2,4,11,6,2,10,8,6,7,9,8,1};var points=new Vector3[faces.Length];var indices=new int[faces.Length];for(int i=0;i<faces.Length;i++){points[i]=v[faces[i]].normalized*.5f;indices[i]=i;}var m=new Mesh{name="Faceted Rock and Shrub"};m.vertices=points;m.triangles=indices;m.RecalculateNormals();m.RecalculateBounds();AssetDatabase.CreateAsset(m,Dir+"/Faceted Shapes.asset");return m; }
    static Mesh ConeMesh() {var v=new List<Vector3>();var t=new List<int>();for(int i=0;i<8;i++){float a=i*Mathf.PI/4,b=(i+1)*Mathf.PI/4;int k=v.Count;v.Add(new Vector3(Mathf.Cos(a)*.5f,0,Mathf.Sin(a)*.5f));v.Add(Vector3.up);v.Add(new Vector3(Mathf.Cos(b)*.5f,0,Mathf.Sin(b)*.5f));t.AddRange(new[]{k,k+1,k+2});}var m=new Mesh{name="Eight Sided Pine Crown"};m.vertices=v.ToArray();m.triangles=t.ToArray();m.RecalculateNormals();AssetDatabase.CreateAsset(m,Dir+"/Pine Crown.asset");return m; }
    static void Rock(Vector3 p,Vector3 size,Transform parent) { if(!Clear(p,Mathf.Max(size.x,size.z)*.5f)||InBackgroundHill(p,1))return;p=OnGround(p);p.y+=size.y*.16f;var g=Shape("Exposed slope rock",rockMesh,p,size,rng.Next(2)==0?stone:lightStone,parent);g.transform.rotation=Quaternion.Euler(R(-12,12),R(0,360),R(-10,10));rockCount++; }
    static void Bush(Vector3 p,float size,Transform parent) { if(!Clear(p,size*.7f)||InBackgroundHill(p,.6f))return;p=OnGround(p);for(int i=0;i<3;i++){var q=p+new Vector3((i-1)*size*.23f,size*.22f,0);var g=Shape("Low scrub",rockMesh,q,new Vector3(size*.8f,size*.7f,size*.75f),i==1?leaf:olive,parent);g.transform.rotation=Quaternion.Euler(0,R(0,360),0);}bushCount++; }
    static void Tree(Vector3 p,float height,Transform parent) {if(!Clear(p,2.5f)||InBackgroundHill(p,1.5f))return;p=OnGround(p);Box("Pine trunk",p+Vector3.up*height*.3f,new Vector3(.22f,height*.6f,.22f),bark,parent);for(int i=0;i<3;i++){float width=height*(.65f-i*.13f);Shape("Sparse pine crown",coneMesh,p+Vector3.up*height*(.23f+i*.18f),new Vector3(width,height*.42f,width),pine,parent);}treeCount++; }
    static void Text(Transform frame,string name,string text,Vector3 local,Vector2 size,float fontSize,Color color,bool back=false) {var g=new GameObject(name,typeof(TextMeshPro));g.transform.SetParent(frame,false);g.transform.localPosition=local;if(back)g.transform.localRotation=Quaternion.Euler(0,180,0);var label=g.GetComponent<TextMeshPro>();label.font=font;label.text=text;label.fontSize=fontSize;label.color=color;label.alignment=TextAlignmentOptions.Center;label.textWrappingMode=TextWrappingModes.NoWrap;label.rectTransform.sizeDelta=size;label.ForceMeshUpdate();}
    static Transform Sign(string name,Vector3 p,Vector3 forward,float width,float height,string heading,string sub,bool arrow=false) {p=OnGround(p);var g=new GameObject(name);g.transform.SetParent(group,false);g.transform.position=p;g.transform.rotation=Quaternion.LookRotation(forward,Vector3.up);for(int i=0;i<2;i++){var post=Box("Timber sign support",p,new Vector3(.16f,2.8f,.16f),timber,g.transform);post.transform.localPosition=new Vector3((i==0?-1:1)*(width*.5f-.2f),1.35f,0);post.transform.localRotation=Quaternion.identity;}var board=Box("Dark sign face",p,new Vector3(width,height,.18f),panel,g.transform);board.transform.localPosition=new Vector3(0,2.35f,0);board.transform.localRotation=Quaternion.identity;Text(g.transform,"Heading",heading,new Vector3(0,2.65f,-.101f),new Vector2(width-.3f,.8f),width>4?5.4f:3.8f,Color.white);Text(g.transform,"Route information",sub,new Vector3(0,2.06f,-.102f),new Vector2(width-.3f,.65f),width>4?2.5f:2.1f,new Color(.98f,.75f,.23f));Text(g.transform,"Reverse face",heading,new Vector3(0,2.4f,.101f),new Vector2(width-.3f,.8f),width>4?4.5f:3.5f,Color.white,true);signCount++;return g.transform; }
    static Vector3 SafeSide(Route route,float d,float offset,float radius,out Vector3 forward) {var p=At(route,d,out forward);var side=Vector3.Cross(Vector3.up,forward);for(float o=offset;o<offset+12;o+=1){var q=p+side*o;if(Clear(q,radius)&&!InBackgroundHill(q,radius))return q;}throw new System.Exception("No clear sign location at "+d);}
    static void Cluster(string name,Vector3 center,bool tree) {var parent=Folder(name);for(int i=0;i<3;i++)Rock(center+new Vector3(R(-2.2f,2.2f),0,R(-2,2)),new Vector3(R(.8f,1.7f),R(.65f,1.15f),R(.8f,1.5f)),parent);for(int i=0;i<3;i++)Bush(center+new Vector3(R(-3,3),0,R(-3,3)),R(.7f,1.3f),parent);if(tree)Tree(center+new Vector3(1.7f,0,2.6f),R(4.2f,5.2f),parent);}
    public static string Main()
    {
        if(EditorApplication.isPlaying)throw new System.Exception("Edit mode required.");for(int i=0;i<SceneManager.sceneCount;i++)if(SceneManager.GetSceneAt(i).isDirty)throw new System.Exception("Save pending scene changes first.");
        var scene=EditorSceneManager.OpenScene("Assets/Scenes/TestTrackScene.unity",OpenSceneMode.Single);root=GameObject.Find("Offroad Course").transform;
        if(root.Find("Offroad scenery and facilities"))throw new System.Exception("Scenery already exists; refusing duplicate props.");if(AssetDatabase.IsValidFolder(Dir))throw new System.Exception("Scenery asset folder already exists.");AssetDatabase.CreateFolder("Assets/Environments/OffroadCourse","Scenery");
        routes=new[]{LoadRoute("Dirt Hill 1",14),LoadRoute("Dirt Hill 2",14),LoadRoute("Gravel Corner 1",14),LoadRoute("Gravel Corner 2",14),LoadRoute("Dirt access road",14),LoadRoute("Truck ridge branch",12)};Physics.SyncTransforms();rng=new System.Random(244);group=new GameObject("Offroad scenery and facilities").transform;group.SetParent(root,false);
        timber=AssetDatabase.LoadAssetAtPath<Material>("Assets/Environments/OffroadCourse/Timber.mat");gold=AssetDatabase.LoadAssetAtPath<Material>("Assets/Environments/TestTrack/Trail_Marker.mat");white=AssetDatabase.LoadAssetAtPath<Material>("Assets/Environments/TestTrack/Track_White.mat");
        stone=Mat("Weathered Rock",new Color(.33f,.35f,.31f));lightStone=Mat("Exposed Stone",new Color(.46f,.45f,.38f));leaf=Mat("Scrub Green",new Color(.27f,.34f,.17f));olive=Mat("Dry Scrub",new Color(.39f,.40f,.21f));pine=Mat("Pine Green",new Color(.15f,.27f,.19f));bark=Mat("Pine Bark",new Color(.23f,.15f,.08f));panel=Mat("Trail Sign Navy",new Color(.035f,.075f,.08f));roof=Mat("Shelter Roof",new Color(.12f,.18f,.2f));gold=Mat("Trail Gold",new Color(.95f,.66f,.14f));font=AssetDatabase.LoadAssetAtPath<TMP_FontAsset>("Assets/Fonts/Nunito/Nunito-Bold SDF.asset");if(font==null)throw new System.Exception("Existing Nunito font missing.");rockMesh=RockMesh();coneMesh=ConeMesh();
        var branch=routes[5];var outcrops=Folder("Hill climb exposed rock and scrub");foreach(float d in new[]{28f,39f,52f,64f}){var p=At(branch,d,out var f);var side=Vector3.Cross(Vector3.up,f);for(int i=0;i<3;i++)Rock(p+side*(11+i*1.6f)+f*R(-2,2),new Vector3(R(1.8f,2.9f),R(1.1f,1.8f),R(1.7f,2.6f)),outcrops);Bush(p+side*15+f*3,1.1f,outcrops);}
        Cluster("South straight scrub island",new Vector3(169,0,-49),true);Cluster("South bend pine island",new Vector3(237,0,-50),true);Cluster("West approach scrub island",new Vector3(106,0,-29),true);Cluster("Low infield rock group",new Vector3(193,0,4),false);Cluster("Low infield scrub group",new Vector3(222,0,6),false);
        var entrance=SafeSide(branch,12,12,2.8f,out var heading);Sign("Hill climb entrance",entrance,Vector3.left,4.6f,1.8f,"HILL CLIMB",">  TRUCK ROUTE  |  17 DEG / 6m");
        if(!Clear(new Vector3(218,0,17),2))throw new System.Exception("Main route sign clearance");Sign("Main loop route arrow",new Vector3(218,0,17),Vector3.left,3.5f,1.5f,"< MAIN LOOP","ALL VEHICLES");
        Sign("Dirt course entrance",new Vector3(103,0,13),Vector3.right,4.5f,1.8f,"OFF-ROAD TEST","DIRT LOOP + HILL CLIMB");
        for(int d=25;d<=100;d+=25){var p=SafeSide(branch,d,8.3f,.8f,out var f);p=OnGround(p);var frame=new GameObject("Distance marker "+d+"m").transform;frame.SetParent(group,false);frame.SetPositionAndRotation(p,Quaternion.LookRotation(f));var post=Box("Timber distance post",p+Vector3.up*.6f,new Vector3(.14f,1.3f,.14f),timber,frame);var face=Box("Distance plaque",p+Vector3.up*1.15f,new Vector3(1.35f,.65f,.1f),panel,frame);face.transform.localRotation=Quaternion.identity;Text(frame,"Distance",d==50?"50m | SUMMIT":d+"m",new Vector3(0,1.15f,-.06f),new Vector2(1.25f,.5f),d==50?1.75f:2.8f,new Color(.98f,.75f,.23f));}
        foreach(float d in new[]{43f,82f}){var p=SafeSide(branch,d,8.3f,.8f,out var f);p=OnGround(p);var frame=new GameObject("Timber route chevron").transform;frame.SetParent(group,false);frame.SetPositionAndRotation(p,Quaternion.LookRotation(f));var post=Box("Chevron post",p+Vector3.up*.6f,new Vector3(.13f,1.3f,.13f),timber,frame);var board=Box("Chevron face",p+Vector3.up*1.15f,new Vector3(.8f,.7f,.1f),panel,frame);board.transform.localRotation=Quaternion.identity;Text(frame,"Direction","<",new Vector3(0,1.15f,-.06f),new Vector2(.7f,.65f),3.8f,gold.color);}
        var shelter=Folder("Marshal shelter 02");var basePos=OnGround(new Vector3(110,0,22));if(!Clear(basePos,3.7f))throw new System.Exception("Shelter clearance");Box("Marshal deck",basePos+Vector3.up*.1f,new Vector3(5.2f,.2f,4),timber,shelter);for(int x=-1;x<=1;x+=2)for(int z=-1;z<=1;z+=2)Box("Shelter timber column",basePos+new Vector3(x*2.1f,1.55f,z*1.5f),new Vector3(.18f,3,.18f),timber,shelter);Box("Marshal roof",basePos+Vector3.up*3.1f,new Vector3(5.3f,.22f,4.1f),roof,shelter);Box("Back windbreak",basePos+new Vector3(0,1.1f,1.5f),new Vector3(4.3f,1.8f,.12f),panel,shelter);Box("Marshal bench",basePos+new Vector3(0,.7f,.8f),new Vector3(2.5f,.16f,.65f),timber,shelter);for(int side=-1;side<=1;side+=2)Box("Bench leg",basePos+new Vector3(side*.9f,.4f,.8f),new Vector3(.14f,.5f,.5f),timber,shelter);var signFrame=new GameObject("Marshal shelter sign").transform;signFrame.SetParent(shelter);signFrame.position=basePos;Box("Marshal name board",basePos+new Vector3(0,2.65f,-1.6f),new Vector3(3.6f,.65f,.12f),panel,shelter);Text(signFrame,"Station name","MARSHAL 02",new Vector3(0,2.65f,-1.67f),new Vector2(3.3f,.55f),3.2f,Color.white);
        foreach(var text in root.GetComponentsInChildren<TextMesh>()){if(text.text.StartsWith("HILL CLIMB")||text.text.StartsWith("DIRT LOOP")||text.text=="MAIN LOOP")text.gameObject.SetActive(false);}foreach(Transform t in root)if(t.name=="Sign post"&&(Vector3.Distance(new Vector3(t.position.x,0,t.position.z),new Vector3(230,0,42))<.1f||Vector3.Distance(new Vector3(t.position.x,0,t.position.z),new Vector3(92,0,10))<.1f||Vector3.Distance(new Vector3(t.position.x,0,t.position.z),new Vector3(219,0,20))<.1f))t.gameObject.SetActive(false);
        AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);Selection.activeGameObject=group.gameObject;
        return $"Added {rockCount} partially buried rocks, {bushCount} low scrub groups, {treeCount} sparse trees, {signCount} two-sided signs, 4 distance markers, 2 route chevrons and a marshal shelter. No prop colliders or driving changes.";
    }
}
